INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES
(11216, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.lesung\",\"sections\":[{\"type\":\"intro\",\"body\":\"Am 19. März 2026 um 18 Uhr war Richard Schimko im Industriesalon zu Gast. Der Physiker, Professor und frühere Forschungsdirektor im Werk für Fernsehelektronik las aus seinem Buch »Ich bin Physiker und Kleinkapitalist«.\\nIm Gespräch ging es um seine Jahre im WF, um Forschung und Mikroelektronik in der DDR sowie um die Umbrüche nach 1990, als aus dem Werk neue Firmen, Konflikte und Wege des Weiterarbeitens hervorgingen.\\nSchimko verbindet Technikgeschichte, Betriebsgeschichte und persönliche Erinnerung aus einer Perspektive, die unmittelbar mit Schöneweide verknüpft ist.\"}]}'),
(13349, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.vortrag\",\"sections\":[{\"type\":\"intro\",\"body\":\"Massarrats These ist unbequem:US-Hegemonie beruht nicht auf Überlegenheit,sondern auf einem System aus Ölkontrolle, Dollardominanz und Militärpräsenz —das sich in der Krise befindet, aber nicht kampflos aufgibt. Er benennt die Risikendes Übergangs zur multipolaren Welt — und zeigt, welche Ansätze eine neueWeltordnung möglich machen könnten.Am 22. April kommt er in den Industriesalon Schöneweide.Wir erwarten einen spannenden Abend mit Zukunftsforscher Klaus Burmeister,Mohssen Massarrat und …Zukunft im Gespräch (ZiG) ist eine kuratierte Gesprächsreihe von WERK116 und Industriesalon Schöneweide.Bücher, Thesen und künstlerische Positionen zu Gegenwart und Zukunft bilden den Ausgangspunkt für Abende, an denenAutorengespräch und Publikumsdialog ineinandergreifen – und das Gespräch in entspannter Salon-Atmosphäre weiterlebt\\n\\nWir danken für die Unterstützung\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"11408\",\"label\":\"fly_m-massarrat_04-1\",\"width\":\"248\",\"height\":\"107\"}]},{\"type\":\"zitat\",\"quote\":\"US-Hegemonie beruht nicht auf Überlegenheit,sondern auf einem System aus Ölkontrolle, Dollardominanz und Militärpräsenz\"}]}'),
(24825, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.vortrag\",\"sections\":[{\"type\":\"intro\",\"body\":\"Zum Auftakt der dreiteiligen Veranstaltungsreihe des Industriesalon zum Tod von Walther Rathenau vor 100 Jahren hält der Historiker Thomas Irmer am 16. Juni, ab 19 Uhr, einen Vortrag über den ehemaligen deutschen Außenminister, Industriellen, Publizisten und Politiker.\\n\\n\\n\\nRathenau wird in dem gut einstündigen Vortrag von Irmer nicht nur in seiner Rolle als Außenminister vorgestellt. Beleuchtet werden auch seine Haltung zum Antisemitismus, seine Beziehung als Vorstandsmitglied der AEG zu Schöneweide insbesondere während des Ersten Weltkrieges und Rathenaus Position zum europäischen Kolonialismus. Ebenso wird der 1922 mit der Russischen Sozialistischen Föderativen Sowjetrepublik unterzeichnete Rapallo-Vertrag ein Thema sein. Der Vertrag normalisierte die Beziehungen der beiden Staaten, die mit ihm ihre jeweilige internationale Isolation nach dem Ersten Weltkrieg durchbrechen wollten.\\n\\n\\n\\nThomas Irmer, Politikwissenschaftler, tätig als Historiker für analoge und digitale Bildungsprojekte zur NS-Zeit,forscht zur Geschichte der AEG, Lehrbeauftragter an der HWR.\\n\\nMehr unter http://www.thomas-irmer.de\\n\\nIm Anschluss daran informiert Agathe Conradi, Leiterin der Museen Treptow-Köpenick, über das Programm zum diesjährigen Gedenken an die \\\"Köpenicker Blutwoche\\\".\\n\\nZum Abschluss der Veranstaltung zeigt der Industriesalon den Film \\\"Mord an Rathenau\\\" aus dem Jahr 1961.\\n\\n&nbsp;\\n\\nWeitere Veranstaltungen zum 100. Todestag vom Walther Rathenau im Industriesalon:\\n\\nDonnerstag, 23. Juni 2022, 19 Uhr: Autorenlesung mit Thomas Hüetlin, Spiegelbestsellerautor, aus seinem Buch \\\"Mord an Walther Rathenau, 24. Juni 1922\\\". Anschließend berichtet das Zentrum für Demokratie über die aktuelle Entwicklung rechtsextremistischer Aktivitäten im Bezirk Treptow-Köpenick - mit Podiumsdiskussion.\\n\\nSamstag, 25. Juni 2022, 13 Uhr: Spezialführung \\\"Auf den Spuren Walther Rathenaus in Oberschöneweide\\\" mit Historiker Dr. Peter Strunk, langjähriger Sprecher der Wista und Archivar der AEG. Start am Industriesalon.\"}]}'),
(24826, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.gespraech\",\"sections\":[{\"type\":\"intro\",\"body\":\"Am 26. September ab 19 Uhr laden wir zu einem spannenden Salongespräch in den Industriesalon: Oberschönweide hat viel Energie zu bieten, so auch ein Unternehmen, das im HTW-Umfeld gegründet jetzt als Rolls-Royce Solutions Berlin GmbH firmiert. Hier werden Lösungen für flexible Energielandschaften entwickelt. Sie folgen den Trends zur Elektrifizierung, Digitalisierung und wollen einen Beitrag zur Dekarbonisierung - also zur Bekämpfung der Klimakrise - leisten. Darüber wollen wir mehr im Gespräch mit Michael H. Hierholzer, Managing Director - Rolls-Royce Solutions Berlin GmbH und amtierender Leiter Transformation sowie strategische Partnerschaften, erfahren, insbesondere über die Zukunft nachhaltiger Energie.\\n\\nNach dem Vortrag werden Klaus Burmeister (Geschäftsführer foresightlab) und Peer Hauschild (Projektleiter Industriesalon) interessiert nachfragen, auch nach der Bedeutung und dem Entwicklungspotenzial des Standortes Oberschönweide.\\n\\nAnschließend laden wir zu einem Get-Together ein. Unser Getränke-Tresen ist geöffnet.\\n\\nDer Eintritt ist frei. Um eine Anmeldung unter info@industriesalon.de wird gebeten.\"}]}'),
(24827, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.gespraech\",\"sections\":[{\"type\":\"intro\",\"body\":\"Dienstag, 15. Oktober 2024, 19 Uhr\\nSalongespräch in Schöneweide: Vielfalt und Toleranz im Kiez - Wie stabil ist das Miteinander?\\n\\nMenschen aus der ganzen Welt studieren, arbeiten und wohnen in Schöneweide. Der Ortsteil hat sich von einem einst extrem rechten Problemgebiet zu einem weltoffenen und bürgergetragenen Kiez entwickelt. Doch wie stabil ist dieses Miteinander? Welche negativen Einflüsse wirken auf die Gemeinschaft? Und welche Gefahren drohen, wenn die Stimmung kippt und extrem rechte Parolen sowie Parteien an Einfluss gewinnen?\\n\\nDas Zentrum für Demokratie und der Industriesalon Schöneweide laden ein zu einem Salongespräch mit Akteur:innen aus Kultur, Wirtschaft, Wissenschaft und Politik. Gemeinsam wollen wir diskutieren, welchen Stellenwert Toleranz und Vielfalt in Schöneweide heute haben und wie der Standort dauerhaft ein lebendiger Kiez bleiben kann.\\n\\nProgramm\\n\\n19:00 Uhr: Begrüßung und Einführung\\nKatja Sternberger (Partnerschaft für Demokratie Schöneweide), Benedikt Hotz (Zentrum für Demokratie) und Klaus Burmeister (Industriesalon Schöneweide)\\n\\nPodiumsdiskussion\\n\\n \\tAsya Aldiri (DIALOG-Integrationszentrum für Migrant*innen; abw gGmbH)\\n \\tLars Düsterhöft, MdA SPD\\n \\tDr. Jette Hausotter (Referentin für Gender, Diversität und Antidiskriminierung, HTW Berlin)\\n \\tMichael Hierholzer (Rolls-Royce Power Systems)\\n \\tVolker Rueß (KAOS CoWorking GmbH)\\n \\tErich Striedl (Unternehmerkreis Schöneweide e.V.)\\n \\tSophia Halamoda (Graphic Recording)\\n\\nModeration: Katja Sternberger, Benedikt Hotz und Klaus Burmeister\\n\\nAb 21:00 Uhr: Open Talk\\n\\nSeien Sie dabei und diskutieren Sie mit uns über die Zukunft von Schöneweide!\"}]}'),
(24828, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.festival\",\"sections\":[{\"type\":\"intro\",\"body\":\"Zeitzeugen aus der Elektropolis\\nSonderprogramm zum Tag des offenen Denkmals am Sonntag, 8.9.2024\\nBei einer Führung durch das historische Industriegebiet werden Videos von ehemaligen Werktätigen an den authentischen Arbeitsorten gezeigt.\\n\\nStart der 1. Führung: 11Uhr\\nStart der 2. Führung: 13Uhr\\n\\nDie Führung ist kostenlos. Eine Anmeldung bis zum 5.9.24 ist erforderlich an: info@industriesalon.de – Stichwort. Tag des offenen Denkmals\\n\\nTreffpunkt: Industriesalon Schöneweide, Reinbeckstraße 10, 12459 Berlin\\nTelefonische Informationen: 030 - 53 00 70 42 (Bürozeiten: Dienstag bis Donnerstag 10 – 16 Uhr, Freitag 10 – 14 Uhr)\\n\\n&nbsp;\\n\\n&nbsp;\"}]}'),
(24829, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.vortrag\",\"sections\":[{\"type\":\"intro\",\"body\":\"13.11.2025 | 19:30 Uhr | Industriesalon Schöneweide\\n\\nWachstum vs. Klimaschutz – geht das zusammen? Nein!, sagt Ulrike Herrmann, Bestsellerautorin und taz-Wirtschaftsredakteurin. In ihrem neuen Buch „Das Ende des Kapitalismus“ erklärt sie, warum wir uns auf „grünes Schrumpfen“ einstellen müssen – wenn wir den Planeten retten wollen.\\n\\nWas erwartet euch?\\n\\n \\tProvokante Thesen &amp; kontroverse Diskussionen\\n \\tModeration: Zukunftsforscher Klaus Burmeister\\n \\tTeil der neuen Reihe „Zukunft im Gespräch“ (Buchhandlung WERK 116 &amp; Industriesalon Schöneweide)\\n\\nEintritt: 14 € (Vorverkauf) | 19 € (Abendkasse)\\n\\nVorverkauf nur in der Buchhandlung WERK 116 – schnell sein lohnt sich!\\n\\n&nbsp;\\n\\n Wir freuen uns auf rege Teilnahme! \"}]}'),
(24830, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.vortrag\",\"sections\":[{\"type\":\"intro\",\"body\":\"Vortrag von Olaf Liebig, OSW und Dr. Christoph Chiaffrino, HU Berlin\\n\\nAls Sohn des kaufmännischen KWO-Direktors Heinrich Peierls wuchs Rudolph Peierls in der „Rathenau Villa“ in Schöneweide auf.\\nDurch seine Forschungen zur Quantenmechanik und Kernphysik gelangte er zu Weltruhm.\\n1943 erhielt er die britische Staatsbürgerschaft und beriet die britische Regierung zum Bau einer eigenen Atombombe.\\n1946 wurde er als „Commander of the Order of the British Empire“ ausgezeichnet.\\n1968 wurde er durch Ritterschlag von der englischen Königin in den Adelsstand erhoben.\\nDas Grabmal der 1921 verstorbenen Mutter Elly Peierls befindet sich auf dem Waldfriedhof Oberschöneweide.\"}]}'),
(24831, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.praesentation\",\"sections\":[{\"type\":\"intro\",\"body\":\"Vorführung des ausgezeichneten Films \\\"Feldliebe\\\" - Eine Liebe die ewig hält: Das Tempelhofer Feld.\\nDokumentarfilm, 90 Min.\\nFür alle Feldfans und Leute, die es werden wollen: Den Film muss man gesehen haben.\\nEintritt frei.\\n\\n&nbsp;\"}]}'),
(24961, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.vortrag\",\"sections\":[{\"type\":\"intro\",\"body\":\"Am 21. Mai 2026 um 19 Uhr spricht Dr.-Ing. Gerd Heinz im Industriesalon über das Institut für Nachrichtentechnik (INT) in Berlin-Schöneweide. Bis zur Wende entwickelten dort 1.640 Mitarbeiter Übertragungssysteme für den gesamten Ostblock.\\nDas INT gehörte zu den geheimnisumwitterten Hightech-Standorten in Schöneweide. Weil Nachrichtentechnik und Mikroelektronik in der DDR unter Embargobedingungen entstanden, unterlagen viele Arbeitsbereiche und ganze Betriebsteile strenger Geheimhaltung.\\nGerd Heinz arbeitete von 1977 bis 1987 selbst am Institut, war an frühen Mikroprozessorsystemen und am ersten Master-Slice-IC der DDR beteiligt und kann die Geschichte des Standorts aus eigener Erfahrung erzählen.\"}]}'),
(24988, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.vortrag\",\"sections\":[{\"type\":\"intro\",\"body\":\"14. Oktober 2025 | 19 Uhr | Industriesalon Schöneweide\\nNew York, Rio – Schöneweide? Dieses Salongespräch fragte nach neuen Wohngebieten, globalen Vergleichen und der Zukunft eines Stadtteils, in dem eines der größten Industriedenkmäler Deutschlands steht.\\nZu Gast waren David Weiblein (BTB), Wyatt Gordon (Stadtplaner und Journalist) und Annette Berfelde (Stadtentwicklungsamt, vorbereitende Stadtplanung). Moderiert wurde der Abend von Jana Birthelmer.\\nIm Mittelpunkt standen Fragen nach städtebaulicher Attraktivität, neuen Nachbarschaften, Investitionsdynamik und den Spielräumen einer sozialen, denkmalbewussten Entwicklung in Schöneweide.\"},{\"type\":\"kapitel\",\"kicker\":\"Thema\",\"title\":\"Worum geht es?\",\"body\":\"Kurze Einordnung des Abends. Der Vortrag setzt ein klares Thema, erklärt den Bezug zum Ort und macht verständlich, warum dieser Termin jetzt relevant ist.\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26558\",\"label\":\"Bild2_Kraftwerk\",\"width\":\"800\",\"height\":\"578\"}]},{\"type\":\"kapitel\",\"kicker\":\"Ablauf\",\"body\":\"18:00 - Einlass - Ankommen und Orientierung\\n18:30 - Vortrag - Impuls mit Bildern, Quellen oder Material\\n19:30 - Gespräch - Fragen und Austausch\"},{\"type\":\"kapitel\",\"kicker\":\"Referent:in\",\"title\":\"Name und Perspektive\",\"body\":\"Kurzer Absatz zur Person, Rolle, Expertise und zum Bezug des Beitrags zum Thema.\"},{\"type\":\"kapitel\",\"kicker\":\"Kontext\",\"title\":\"Warum dieser Abend?\",\"body\":\"Hier steht der Zusammenhang mit Schöneweide, dem Industriesalon, einer Ausstellung, einem Projekt oder einer aktuellen Debatte.\",\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26428\",\"label\":\"image2\",\"width\":\"830\",\"height\":\"912\"}]},{\"type\":\"material\",\"kicker\":\"Materialien\",\"title\":\"Downloads und Quellen\",\"items\":[\"PDF - Vortragsfolien, Handout oder Manuskript - Download\",\"Link - Weiterführende Quelle, Projektseite oder Literaturhinweis - extern\"],\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"26428\",\"label\":\"image2\",\"width\":\"830\",\"height\":\"912\"}],\"object_refs\":[{\"kind\":\"archive_object\",\"source\":\"iss-archive\",\"id\":\"15127\",\"label\":\"Informationstext über das NEF auf kyrillisch. Die Übersetzung lautet: In dem auf dem Gelände des Werkes FAO AEG gelegenen Büro, das sich in…\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/05/Album_NEF_Seite_03-150x150.jpg\",\"set_id\":\"19\",\"member_id\":\"4469\",\"set_title\":\"NEF-Album\"}]}]}'),
(24991, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.gespraech\",\"sections\":[{\"type\":\"intro\",\"body\":\"Juni 2023 | Industriesalon Schöneweide\\nMehr als 100 Gäste kamen zum Salongespräch über die Zukunft des ehemaligen WF-Areals. Robert Sprajcar stellte das Projekt Behrens-Ufer vor; Klaus Burmeister und Stefanie Molthagen-Schnöring moderierten die Diskussion.\\nIm Zentrum standen Öffnung des Areals, Gemeinwohlfragen, Energieversorgung, Denkmalschutz und die Folgen für Oberschöneweide.\\nDie Debatte gewann zusätzliche Bedeutung, weil die DIEAG das ehemalige Industrieareal entlang der Spree als offenes Gewerbequartier mit Laboren, Technologiezentren, Kultur, Gastronomie, Einzelhandel und sozialen Einrichtungen entwickelt. Nach Angaben der DIEAG umfasst das Vorhaben rund 100.000 m² Arealfläche und ein Investitionsvolumen von rund 1,1 Mrd. Euro.\"}]}'),
(24992, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.festival\",\"sections\":[{\"type\":\"intro\",\"body\":\"Juli 2024 | Brückenfest Schöneweide\\nZum Brückenfest öffnete der Industriesalon seine Ausstellung 15 Jahre Industriesalon und beteiligte sich mit Führungen, Büchertisch und Mitmachangeboten am gemeinsamen Nachbarschaftsfest.\\nZum Programm gehörten eine Zeitzeugenführung zu Exponaten aus dem Werk für Fernsehelektronik und eine Blitztour vom Kaisersteg zum Transformatorenwerk. Ergänzt wurde das Programm durch einen Büchertisch des Vereins SchreibART.\\nDer Beitrag machte sichtbar, wie der Industriesalon lokale Erinnerungsarbeit, Tourismus und Nachbarschaftsnetzwerke im öffentlichen Raum miteinander verbindet.\"}]}'),
(24993, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.festival\",\"sections\":[{\"type\":\"intro\",\"body\":\"1. Oktober 2017 | Peter-Behrens-Bau und Wilhelminenhofstraße\\nZum 100. Jahrestag des Produktionsbeginns der Nationalen Automobil-Gesellschaft im Peter-Behrens-Bau organisierten der Industriesalon, die Initiative Wilhelminenhofstraße und der Unternehmerkreis Schöneweide das Straßenfest Boxenstopp – ein Fest der Mobilität.\\nGeschäfte und Einrichtungen entlang der Wilhelminenhofstraße wurden zu „Boxenstopps“, auf der Bühne vor dem Peter-Behrens-Bau startete ein Autokorso mit historischen Fahrzeugen und neuen Elektro-Autos.\\nAm Abend wurde der Peter-Behrens-Bau im Rahmen von Berlin leuchtet mit einer 3D-Videolichtshow inszeniert. Das Fest stellte Industriekultur, Mobilität und Standortnetzwerke in Schöneweide sichtbar zusammen.\"}]}'),
(25661, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.workshop\",\"sections\":[{\"type\":\"intro\",\"body\":\"Erstes Vorbereitungstreffen zur Futura Biennale 2027 im Industriesalon Schöneweide. Im Mittelpunkt stehen Vorhaben für Schöneweide 2030, mögliche Beiträge und weitere Akteure, die an den Tisch gehören.\"}]}'),
(25729, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.workshop\",\"sections\":[{\"type\":\"intro\",\"body\":\"Das Schöneweider Salongespräch stellte den Übergang des Werks für Fernsehelektronik nach 1990 als Geschichte von Wissenstransfer, Ausgründung und neuer industrieller Praxis vor.\\n\\nDr. Peter Strunk eröffnete mit einer Einführung zum Werk für Fernsehelektronik in Berlin-Schöneweide und zum Verschwinden der Industrie in Berlin nach 1989. Anschließend diskutierten Vertreterinnen und Vertreter erfolgreicher ehemaliger WF-Mitarbeiter und Ausgründungen über Erfahrungen aus der DDR-Industrie, Gründungspraxis und Standortkompetenz.\\n\\nFür den Industriesalon ist diese Veranstaltung ein wichtiger Übergangspunkt zwischen WF-Geschichte, Transformationszeit und den heutigen Technologie- und Zukunftsorten in Schöneweide.\"},{\"type\":\"kapitel\",\"title\":\"Programm\",\"body\":\"Quelle: Bezirksamt Treptow-Köpenick, Pressemitteilung vom 05.04.2019.\"}]}'),
(25749, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.gespraech\",\"sections\":[{\"type\":\"intro\",\"body\":\"Das Regionalmanagement Berlin Südost, der Industriesalon und der Unternehmerkreis Schöneweide luden zu einem Salongespräch über neue Eigentümer, Projektideen, Gewerbeentwicklung und die Rolle der HTW Berlin am Zukunftsort Schöneweide ein.\\n\\nDie Veranstaltung gehört in die Linie der Schöneweider Salongespräche, in denen Standortentwicklung, Industrieerbe und gegenwärtige Transformation öffentlich verhandelt wurden.\"},{\"type\":\"kapitel\",\"title\":\"Quelle\",\"body\":\"Quelle: Berlin.de-Pressemitteilung\"}]}'),
(25751, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.vortrag\",\"sections\":[{\"type\":\"intro\",\"body\":\"Das Salongespräch stellte Objects Manufacturing und die neue Vinylproduktion im historischen Kabelwerk vor. Daniel Plasch sprach über nachhaltige Produktion, Standortentscheidung und die Zukunftspläne des Unternehmens.\"},{\"type\":\"kapitel\",\"title\":\"Programm\",\"body\":\"17:00 Uhr: Führung durch die Produktionshalle in der Wilhelminenhofstraße 76/7719:00 Uhr: Begrüßung und Gespräch im IndustriesalonAnschließend: Diskussion und Get-together\"},{\"type\":\"kapitel\",\"title\":\"Quelle\",\"body\":\"Quelle: Berlin.de-Pressemitteilung\"}]}'),
(25753, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.festival\",\"sections\":[{\"type\":\"intro\",\"body\":\"Zum Tag des offenen Denkmals 2019 bündelte der Industriesalon Führungen, Ausstellung und Musik zu einem offenen Wochenende. Das Programm führte unter anderem in die historische AEG-Kantine, durch Wohn- und Industriebauten der Elektropolis und in das Transformatorenwerk.\"},{\"type\":\"kapitel\",\"title\":\"Programmpunkte\",\"body\":\"Spurensuche in der historischen AEG-KantineEröffnung von Kunst trifft Industrie 2.0Spezialführungen zu Wohnen und TageslichtfabrikenJazzkonzert im Industriesalon\"},{\"type\":\"kapitel\",\"title\":\"Quelle\",\"body\":\"Quelle: Berlin.de-Pressemitteilung\"}]}'),
(25755, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.festival\",\"sections\":[{\"type\":\"intro\",\"body\":\"Der Industriesalon und Basecamp Student GmbH luden zum Tag des offenen Denkmals 2020 zu zwei Rundgängen durch das historische Transformatorenwerk Oberschöneweide ein.\\n\\n13:00 Uhr: Historischer Industriebau und Denkmalschutz15:00 Uhr: Das Transformatorenwerk in Transformation\"},{\"type\":\"kapitel\",\"title\":\"Quelle\",\"body\":\"Quelle: Berlin.de-Pressemitteilung\"}]}'),
(25757, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.festival\",\"sections\":[{\"type\":\"intro\",\"body\":\"Unter dem Motto „Schöneweide - voller Energie“ wurde die Wilhelminenhofstraße zum Boulevard der Industriekultur. Der Industriesalon war zentraler Ausgangs- und Infopunkt für Führungen und Angebote im Umfeld historischer Hallen, Produktionsorte, Ausstellungshäuser und Ateliers.\\n\\nDas Programm verband Denkmalpflege, aktuelle Produktion, Kulturorte und Science-Fiction-Bezüge und zeigt die Rolle des Industriesalons als Knotenpunkt im Stadtteil.\"},{\"type\":\"kapitel\",\"title\":\"Quelle\",\"body\":\"Quelle: Berlin.de-Pressemitteilung\"}]}'),
(25759, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.festival\",\"sections\":[{\"type\":\"intro\",\"body\":\"Die Festwoche zum zehnjährigen Bestehen des Industriesalons bündelte Ausstellungen, Führungen, Film, Repair-Café, Salongespräch, Herbstlese, Familienfest und Jazzcafé. Sie ist ein wichtiger Marker für die Selbstbeschreibung des Hauses als Vermittlungsort der Elektropolis.\"},{\"type\":\"kapitel\",\"title\":\"Programmspuren\",\"body\":\"Auftakt mit Enthüllung des Röhrenträgers und Ausstellungen aus WF-Fotosammlung und Stöber-ArchivTouren zu Arbeitswelten, Lichtfabriken und modernem Wohnen in der IndustriestadtSalongespräch „Neuer Wind am Zukunftsort“Geburtstagsfest und Jazzcafé\"},{\"type\":\"kapitel\",\"title\":\"Quelle\",\"body\":\"Quelle: Berlin.de-Pressemitteilung\"},{\"type\":\"kapitel\",\"title\":\"Programm-PDF\",\"body\":\"Festwoche Programm.pdfHerunterladen\"}]}'),
(25761, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.vortrag\",\"sections\":[{\"type\":\"intro\",\"body\":\"Zum Auftakt der dreiteiligen Rathenau-Reihe sprach der Historiker Thomas Irmer über Walther Rathenau als Außenminister, Industriellen, Publizisten und Politiker. Der Vortrag stellte auch Rathenaus Verhältnis zu Antisemitismus, AEG und Schöneweide sowie zum europäischen Kolonialismus in den Blick.\\n\\nIm Anschluss informierte Agathe Conradi über das Programm zum Gedenken an die Köpenicker Blutwoche; der Abend schloss mit dem Film „Mord an Rathenau“.\"},{\"type\":\"kapitel\",\"title\":\"Quelle\",\"body\":\"Quelle: Berlin.de-Kulturnewsletter\"}]}'),
(25774, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.lesung\",\"sections\":[{\"type\":\"intro\",\"body\":\"Im Rahmen des Rathenau-Gedenkprogramms las Thomas Hüetlin aus seinem Buch über die Ermordung Walther Rathenaus. Anschließend berichtete das Zentrum für Demokratie über aktuelle rechtsextreme Aktivitäten im Bezirk und in Berlin.\"},{\"type\":\"kapitel\",\"title\":\"Quelle\",\"body\":\"Quelle: Berlin.de-Pressemitteilung\"}]}'),
(25808, '_iss_content_json', '{\"schema_version\":1,\"entity_key\":\"event.festival\",\"sections\":[{\"type\":\"intro\",\"body\":\"Programm\"},{\"type\":\"kapitel\",\"title\":\"Live-Musik zwischen 15 und 22 Uhr\",\"body\":\"Zum Sommeranfang spielen sieben Acts im Industriesalon. Die Reihenfolge steht im Flyer; einzelne Set-Zeiten werden separat vor Ort bekanntgegeben.\\n\\nLiveKWO-Klangwerk OberspreeBigband mit PowerLiveThe Velvet EchoesWarmer HarmoniegesangLiveJakabLieder mit GeschichtenLiveCrimson SundayUltimativer Retro-RockLiveIzzy DiazTanzbarer Folk aus SpanienLiveFranziskas ErbenPunk-Pop mit TiefgangLiveDances with DogsRock voller Überraschungen\"},{\"type\":\"kapitel\",\"title\":\"Vor Ort\",\"body\":\"Live-Musik, kühle Getränke und offene Hofatmosphäre im Industriesalon. Kommen und Gehen ist jederzeit möglich.\"},{\"type\":\"kapitel\",\"title\":\"Ort\",\"dynamic_refs\":[{\"kind\":\"control_field\",\"source\":\"industriesalon-steuerung\",\"key\":\"address.full\",\"label\":\"Volle Adresse\",\"tagName\":\"p\",\"linkMode\":\"none\"}]},{\"type\":\"kapitel\",\"title\":\"Eintritt\",\"body\":\"Der Eintritt ist frei. Eine Anmeldung ist nicht erforderlich.\"}]}');
